"use client";
import React, { useEffect, useState } from "react";
import { Button, Card, Popover, Table, Image, Form, Input, Row, Col, Typography, Tooltip, Switch, Space, Tag, Modal, Divider } from "antd";
import { ColumnsType } from "antd/lib/table";
import Link from "next/link";
import { FilterOutlined, PlusCircleOutlined, UpCircleOutlined, DownCircleOutlined, PaperClipOutlined, MenuOutlined } from "@ant-design/icons";
import { exportIcon } from "@/components/icon";
import { TableProductLot } from "./TableProductLot";
import { ITypeMasterProduct } from "../common";
import { numberWithCommas } from "@/app/utils/format";
import { TableDetailLot } from "./TableDetailLot";
import { checkRule } from "@/app/utils/rules";
import { InventoryStockServices } from "../../inventory/services/inventory-stock.service";
import { useAxiosStock } from "@/app/lib/axios/hooks/userAxiosAuth";
export interface props {
  dataTable: ITypeMasterProduct[];
  onFilter?: (event: object) => void;
  openFilter?: boolean;
  handleOpenFilter: (value: boolean) => void;
  loading: boolean;
  getswitch: boolean;
  setSwitch: (value: boolean) => void;
}

const ProductList: React.FC<props> = ({ dataTable, onFilter, openFilter, handleOpenFilter, loading, getswitch, setSwitch }): React.ReactElement => {
  const addOrderRule = checkRule("sm-order-a");
  const stockAuth = useAxiosStock();
  const inventorystockservices = InventoryStockServices(stockAuth);
  const [detailForm] = Form.useForm();

  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalDetail, setModalDetail] = useState<ITypeMasterProduct>();

  useEffect(() => {}, [modalDetail]);

  const formatQtypattern = (qty: number, minimum: number) => {
    let stringQty = numberWithCommas(qty);
    if (Number(qty) < minimum && Number(qty) > 0) {
      return (
        <>
          <Space>
            {stringQty}
            <Tag color="yellow">{`Low`}</Tag>
          </Space>
        </>
      );
    } else if (Number(qty) <= 0) {
      return (
        <>
          <Space>
            {stringQty}
            <Tag color="volcano">{`Out of Stock `}</Tag>
          </Space>
        </>
      );
    } else {
      return (
        <>
          <Space>{stringQty}</Space>
        </>
      );
    }
  };

  const showModal = (object: ITypeMasterProduct) => {
    setModalDetail(object);
    setIsModalOpen(true);
  };

  const handleOk = () => {
    setIsModalOpen(false);
  };

  const handleCancel = () => {
    setIsModalOpen(false);
  };

  const downloadFile = async (id: any, name: string) => {
    if (id) {
      const response = await inventorystockservices.downloadfile(id);
      console.log(response);
      const url = URL.createObjectURL(response);
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }
  };

  const columns: ColumnsType<ITypeMasterProduct> = [
    {
      title: "CAS NO.",
      dataIndex: "casNo",
      key: "casNo",
      width: "20%",
      render: (d: string, r: ITypeMasterProduct, i: number) => (
        <span key={i} className="text-blue cursor-pointer" onClick={() => showModal(r)}>
          {d}
        </span>
      ),
    },
    {
      title: "IMAGE",
      dataIndex: "masterProductDetails",
      key: "masterProductDetails",
      render: (d: { name: string }[], r: ITypeMasterProduct, i: number) => {
        return (
          <>
            <Row gutter={[8, 8]}>
              <Col>
                {r.images ? (
                  <Image src={URL.createObjectURL(r?.images)} width={60} />
                ) : (
                  <Image
                    preview={false}
                    width={60}
                    src="error"
                    fallback="data:image/png;base64,"
                  />
                )}
              </Col>
            </Row>
          </>
        );
      },
    },
    {
      title: "PRODUCT NAME",
      dataIndex: "masterProductDetails",
      key: "masterProductDetails",
      width: "20%",
      render: (d: { name: string }[], r: ITypeMasterProduct, i: number) => {
        return (
          <div>
            <Row gutter={[8, 8]}>
              <Col>
                <div key={i}>
                  <Tooltip
                    key={i}
                    title={
                      <div>
                        {r?.imagesGhs ? (
                          <div
                            key={i}
                            style={{
                              display: "flex",
                              flexWrap: "wrap",
                              justifyContent: "center",
                            }}
                          >
                            {r?.imagesGhs?.map((e: { imagefile: Blob }, index: number) => {
                              return e?.imagefile ? (
                                <div key={i + "-" + index}>
                                  <Image width={40} height={40} preview={false} src={e?.imagefile ? URL.createObjectURL(e.imagefile) : ""} />
                                </div>
                              ) : (
                                <div key={i + "-" + index}>
                                  <Image
                                    width={40}
                                    height={40}
                                    src="error"
                                    preview={false}
                                    fallback="data:image/png;base64,"
                                  />
                                </div>
                              );
                            })}
                          </div>
                        ) : (
                          ""
                        )}
                      </div>
                    }
                  >
                    {d.map((text, index) => (
                      <React.Fragment key={index}>
                        <Tag color="blue" className=" mb-1">
                          {text.name}
                        </Tag>
                        <br />
                      </React.Fragment>
                    ))}
                  </Tooltip>
                </div>
              </Col>
            </Row>
          </div>
        );
      },
    },
    {
      title: "LOCATION",
      dataIndex: "masterProductLocationMap",
      key: "chemicalFormula",
      width: "20%",
      render: (location: { location: { locationName: string } }[]) =>
        location.map((data: { location: { locationName: string } }) => <Tag>{data?.location?.locationName}</Tag>),
    },
    {
      title: "CHEMICAL FORMULA",
      dataIndex: "chemicalFormula",
      key: "chemicalFormula",
      width: "20%",
    },

    {
      title: "GROUP",
      dataIndex: ["masterProductGroup", "groupName"],
      key: "masterProductGroup",
      width: "10%",
    },
    { title: "BRAND", dataIndex: "brandName", key: "brandName", width: "10%" },
    {
      title: "VENDER",
      dataIndex: "venderName",
      key: "venderName",
      width: "10%",
    },
    {
      title: "QTY",
      dataIndex: "calTotalQty",
      key: "calTotalQty",
      width: "10%",
      render: (event: string, row: ITypeMasterProduct, index: number) => {
        if (row?.inventoryStock.length <= 0) {
          return (
            <Space>
              {numberWithCommas(event)}
              <Tag color="volcano">{`Out of Stock `}</Tag>
            </Space>
          );
        } else {
          return formatQtypattern(Number(event), Number(row.minimumStock));
        }
      },
    },
    {
      title: "QTY (EXP.)",
      dataIndex: "expiredRemain",
      key: "expiredRemain",
      align: "right",
      width: "10%",
      render: (event: number, row: ITypeMasterProduct, index: number) => {
        return row?.inventoryStock.length === 0 ? numberWithCommas(0) : <>{numberWithCommas(event)}</>;
      },
    },
    {
      title: "UNIT",
      dataIndex: ["unit", "unitName"],
      key: "unit",
      width: "5%",
    },
    Table.EXPAND_COLUMN,
  ];

  const searchContent = (
    <Form layout="vertical" onFinish={onFilter} autoComplete="off">
      <div className="grid grid-cols-1 md:gap-4 md:grid-cols-4">
        <Form.Item label="Product Name" name="productName">
          <Input placeholder="Search Text" />
        </Form.Item>
        <Form.Item label="Chemical Formula" name="chemicalFormula">
          <Input placeholder="Search Text" />
        </Form.Item>
        <Form.Item label="Cas No." name="casNo">
          <Input placeholder="Search Text" />
        </Form.Item>
        <Form.Item label="Unit" name="unitName">
          <Input placeholder="Search Text" />
        </Form.Item>
        <Form.Item label="Minimum" name="minumumStock">
          <Switch
            checkedChildren="Low"
            unCheckedChildren="All"
            defaultChecked={false}
            onChange={setSwitch}
            className={getswitch === true ? "active-switch" : "inactive-switch"}
          />
        </Form.Item>
        <div className=" md:col-span-4">
          <Form.Item
            style={{
              justifyContent: "end",
              display: "flex",
              alignItems: "center",
            }}
          >
            <Button className=" mr-2">Reset</Button>
            <Button type="primary" htmlType="submit">
              {`Search`}
            </Button>
          </Form.Item>
        </div>
      </div>
    </Form>
  );
  return (
    <>
      {isModalOpen ? (
        <Modal
          title={<div className=" text-2xl">{modalDetail?.casNo}</div>}
          open={isModalOpen}
          onOk={handleOk}
          onCancel={handleCancel}
          footer={false}
          width={1500}
        >
          <Row gutter={[8, 8]}>
            <Col span={24}>
              <Form
                layout={"horizontal"}
                form={detailForm}
                labelAlign="left"
                labelWrap
                // wrapperCol={{ flex: 1 }}
                labelCol={{ flex: "200px" }}
                colon={false}
              >
                <Row>
                  <Col span={24}>
                    <Form.Item label={<div style={{ color: "#9E9E9E" }}>{`Inventory :`}</div>}>
                      <Typography>{`${modalDetail?.masterProductLocationMap[0].location?.locationName}`}</Typography>
                    </Form.Item>
                  </Col>
                  <Col span={24}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Product Image :`}</div>}>
                      {modalDetail?.images ? (
                        <Image width={100} height={100} preview={false} src={modalDetail?.images ? URL.createObjectURL(modalDetail?.images) : ""} />
                      ) : (
                        <Image
                          width={100}
                          height={100}
                          src="error"
                          preview={false}
                          fallback="data:image/png;base64,"
                        />
                      )}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Product Name :`}</div>}>
                      {modalDetail?.masterProductDetails.map((d: { name: string }, index: number) => (
                        <Tag color="blue" className=" text-sm" key={index + 1}>
                          {d.name}
                        </Tag>
                      ))}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`CAS No. :`}</div>}>
                      {modalDetail?.casNo}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Chemical Formula :`}</div>}>
                      {modalDetail?.chemicalFormula}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Category :`}</div>}>
                      {modalDetail?.masterProductGroup?.masterProductCategories?.categoryName}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Group :`}</div>}>
                      {modalDetail?.masterProductGroup?.groupName}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Hazard Type :`}</div>}>
                      {modalDetail?.masterProductHazardtypeMap?.map((d) => (
                        <Tag>{d.masterHazardtype.nameHazard}</Tag>
                      ))}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`GHS :`}</div>}>
                      {modalDetail?.imagesGhs ? (
                        <div style={{ display: "flex", flexWrap: "wrap" }}>
                          {modalDetail?.imagesGhs?.map((e: { imagefile: Blob }, index: number) =>
                            e?.imagefile ? (
                              <div key={index} className=" m-1">
                                <Image width={35} height={35} preview={false} src={e?.imagefile ? URL.createObjectURL(e.imagefile) : ""} />
                              </div>
                            ) : (
                              <Image
                                width={25}
                                height={25}
                                src="error"
                                preview={false}
                                fallback="data:image/png;base64,"
                              />
                            )
                          )}
                        </div>
                      ) : (
                        <Image
                          width={35}
                          height={35}
                          src="error"
                          preview={false}
                          fallback="data:image/png;base64,"
                        />
                      )}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Brand :`}</div>}>
                      {modalDetail?.brandName}
                    </Form.Item>
                  </Col>{" "}
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Vender :`}</div>}>
                      {modalDetail?.venderName}
                    </Form.Item>
                  </Col>
                  {/* <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Type :`}</div>}>
                      {modalDetail?.masterProductGroup?.masterProductGroupMapType ? (
                        <div style={{ display: "flex", flexWrap: "wrap" }}>
                          {modalDetail?.masterProductGroup?.masterProductGroupMapType?.map((event: { typeName: string }, index: number) => {
                            return (
                              <div className="m-0.5" key={index}>
                                <Tag>{event?.typeName}</Tag>
                              </div>
                            );
                          })}
                        </div>
                      ) : null}
                    </Form.Item>
                  </Col> */}
                </Row>
                <div style={{ marginBottom: "-10px", marginTop: "-20px" }}>
                  <Divider />
                </div>
                <Row gutter={[8, 8]}>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Unit :`}</div>}>
                      {modalDetail?.unit?.unitName}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Min Stock :`}</div>}>
                      {numberWithCommas(modalDetail?.minimumStock)}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Max Stock :`}</div>}>
                      {numberWithCommas(modalDetail?.maximumStock)}
                    </Form.Item>
                  </Col>
                  <Col span={8}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`ผู้อัพเดตล่าสุด :`}</div>}>
                      {modalDetail?.updatedByName}
                    </Form.Item>
                  </Col>
                  <Col span={16}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`ลิงค์ภายนอก :`}</div>}>
                      <a href={`${modalDetail?.hyperlink}`} target="_blank">
                        {modalDetail?.hyperlink}
                      </a>
                    </Form.Item>
                  </Col>
                  <Col span={24}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Description :`}</div>}>
                      {modalDetail?.description}
                    </Form.Item>
                  </Col>
                  <Col span={24}>
                    <Form.Item className="mb-2" label={<div style={{ color: "#9E9E9E" }}>{`Attach File :`}</div>}>
                      {modalDetail?.masterProductFiles.map((data: any, index: number) => (
                        <div key={index}>
                          <Button type="link" onClick={() => downloadFile(data.id, data.namefile)}>
                            <Space>
                              <PaperClipOutlined />
                              {data.namefile}
                            </Space>
                          </Button>
                        </div>
                      ))}
                    </Form.Item>
                  </Col>
                </Row>
              </Form>
            </Col>
            <Col span={24}>
              <Card>
                <Typography style={{ fontWeight: "bold", marginBottom: "10px" }}>
                  <Space>
                    <MenuOutlined />
                    {`Lot Lists`}
                  </Space>
                </Typography>
                <TableDetailLot
                  key={String(modalDetail?.inventoryStock[0]?.id)}
                  getId={String(modalDetail?.inventoryStock[0]?.id)}
                  getUnit={modalDetail?.unit?.unitName}
                  getMinStock={modalDetail?.minimumStock}
                />
              </Card>
            </Col>
          </Row>
        </Modal>
      ) : (
        ""
      )}
      <Card style={{ width: "100%", overflowX: "auto" }}>
        <div className=" flex justify-end pb-4">
          <Space>
            <Popover
              onOpenChange={handleOpenFilter}
              open={openFilter}
              content={searchContent}
              placement="bottomLeft"
              title="Search"
              trigger="click"
              overlayStyle={{ width: "calc(100% - 240px)" }}
            >
              <Button type="primary" className="button-blue" icon={<FilterOutlined />}>
                {`Filters`}
              </Button>
            </Popover>
            {addOrderRule ? (
              <Link href="/page/order-management/add">
                <Button className="button-blue" icon={<PlusCircleOutlined />} type="primary">
                  {`Request Order`}
                </Button>
              </Link>
            ) : (
              <></>
            )}
          </Space>
        </div>
        <Table
          size="small"
          rowKey={(e: any) => e.id}
          loading={loading}
          columns={columns}
          dataSource={dataTable}
          bordered={false}
          expandable={{
            expandedRowRender: (record, index) => (
              <div key={index}>
                <TableProductLot record={record} />
              </div>
            ),
            expandIcon: ({ expanded, onExpand, record }) =>
              expanded ? <UpCircleOutlined onClick={(e) => onExpand(record, e)} /> : <DownCircleOutlined onClick={(e) => onExpand(record, e)} />,
          }}
        />
      </Card>
    </>
  );
};

export default ProductList;
